import { chromium } from '@playwright/test'

const base = process.argv[2] || 'http://127.0.0.1:8099'
const out = process.argv[3] || 'D:/repository/_font14_pre.png'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
page.on('console', m => { if (m.type() === 'error') console.log('PAGE-ERR:', m.text()) })
await page.goto(base + '/#/pages/inspection/index?kind=pre', { waitUntil: 'networkidle', timeout: 30000 }).catch(e => console.log('goto:', e.message))
await page.waitForTimeout(2500)

// report computed font sizes of key fields
const sizes = await page.evaluate(() => {
  const pick = sel => {
    const el = document.querySelector(sel)
    if (!el) return null
    return { sel, fs: getComputedStyle(el).fontSize, text: (el.textContent || '').trim().slice(0, 20) }
  }
  return ['field-label', 'upload-label', 'field-input', 'sec-item-label', 'seg-choice', 'choice'].map(c => pick('.' + c)).filter(Boolean)
})
console.log('SIZES:', JSON.stringify(sizes, null, 2))

await page.screenshot({ path: out, fullPage: true })
console.log('screenshot saved', out)
await browser.close()

